from .shared_db import SharedProxyDb

OPTIONAL_CREATE_NAA_TABLE_SQL = """CREATE TABLE IF NOT EXISTS naa_protocol (
                                   port INTEGER PRIMARY KEY,
                                   pid INTEGER,
                                   naa_protocol TEXT,
                                   access TEXT
                               )"""
UPDATE_NAA_PROTOCOL_RECORD_SQL = """INSERT OR REPLACE INTO naa_protocol (port, pid, naa_protocol, access)
                                    VALUES (?, ?, ?, ?)"""
REMOVE_NAA_PROTOCOL_RECORD_SQL = """DELETE FROM naa_protocol WHERE port = ?"""
GET_ALL_NAA_PROTOCOL_RECORDS_SQL = """SELECT port, pid, naa_protocol, access FROM naa_protocol"""
GET_NAA_PROTOCOL_BY_PORT_RECORD_SQL = """SELECT port, pid, naa_protocol, access FROM naa_protocol WHERE port = ?"""
GET_ALL_PORTS_SQL = "SELECT port FROM naa_protocol;"


class SharedProxyDbNaaProtocol(SharedProxyDb):
    """Class to manage 'naa_protocol' table in UE proxies database."""

    class Row:
        """Class representing a row in the 'naa_protocol' table."""
        def __init__(self, port: int, pid: int, naa_protocol: str, access: str):
            self.port = port
            self.pid = pid
            self.naa_protocol = naa_protocol
            self.access = access

    def __init__(self):
        """Initialize the ProxyDatabaseManager class."""
        super().__init__()

    @property
    def TABLE_NAME(self) -> str:
        """Return the name of the table managed by this class."""
        return "naa_protocol"

    async def optional_create_table(self) -> bool:
        """
        Create 'naa_protocol' table if it doesn't exist.

        :returns: True if successful, False otherwise.
        """
        try:
            await self.commit_sql_and_raise_on_failure(OPTIONAL_CREATE_NAA_TABLE_SQL)
            self.logger.info(f"Shared DB ('{self.TABLE_NAME}'): Database updated at: {self.db_path}")
            return True
        except Exception as e:
            self.logger.warning(f"Shared DB ('{self.TABLE_NAME}'): Failed to update database: {e}")
            return False

    async def add_or_update(self, port: int, pid: int, naa_protocol: str, access: str) -> None:
        """
        Add or update a proxy entry in the database.

        :param port: The proxy port number.
        :param pid: The process ID.
        :param naa_protocol: The NAA protocol type.
        :param access: The UE type.
        """
        await self.commit_sql(UPDATE_NAA_PROTOCOL_RECORD_SQL, (port, pid, naa_protocol, access))
        self.logger.debug(f"Shared DB ('{self.TABLE_NAME}'): Tried to add/update proxy entry: ({port=}, {pid=}, "
                          f"{naa_protocol=}, {access=})")

    async def remove_by_port(self, port: int) -> None:
        """
        Remove a proxy entry from the database by port.

        :param port: The proxy port to remove.
        """
        await self.commit_sql(REMOVE_NAA_PROTOCOL_RECORD_SQL, (port,))
        self.logger.debug(f"Shared DB ('{self.TABLE_NAME}'): Tried to remove entry with port {port}")

    async def get_all(self) -> list:
        """
        Get all proxy entries from the database.

        :returns: List of Row objects containing (port, pid, naa_protocol, access).
        """
        results = await self.execute_sql(GET_ALL_NAA_PROTOCOL_RECORDS_SQL)
        self.logger.debug(f"Shared DB ('{self.TABLE_NAME}'): Retrieved all ue-proxy entries, count: {len(results)}")
        return [self.Row(port=row[0], pid=row[1], naa_protocol=row[2], access=row[3]) for row in results]

    async def get_by_port(self, port: int) -> Row:
        """
        Get the NAA protocol of a proxy by its port.

        :param port: The proxy port to look up.
        :returns: Row object containing (port, pid, naa_protocol, access) or None if not found.
        """
        results = await self.execute_sql(GET_NAA_PROTOCOL_BY_PORT_RECORD_SQL, (port,))
        result = results[0] if len(results) > 0 else []
        self.logger.debug(f"Shared DB ('{self.TABLE_NAME}'): Retrieved ue-proxy entry: {result}")
        return self.Row(port=result[0], pid=result[1], naa_protocol=result[2], access=result[3]) if result else None

    async def get_all_ports(self) -> list:
        """
        Retrieve all port numbers from the table 'naa_protocol'.

        :returns: List of port numbers.
        """
        ports = [row[0] for row in await self.execute_sql(GET_ALL_PORTS_SQL)]
        ports_str = [str(port) for port in ports]
        self.logger.debug(f"Shared DB ('{self.TABLE_NAME}'): Retrieved running ue-proxy ports: {', '.join(ports_str)}")
        return ports
